@admin_bp.route("/maintenance", methods=["POST"])
@require_role("admin")
def run_maintenance():
    """Purge audit-log entries for a user (maintenance procedure)."""
    user_id = request.args.get("user_id", "")
    conn = get_engine().raw_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("DELETE FROM audit_log WHERE user_id = ?", (user_id,))
        conn.commit()
    finally:
        conn.close()
    return jsonify({"status": "maintenance complete"})

def require_role(minimum_role: str):
    """Require at least the given role (user < manager < admin)."""

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)

        return wrapper

    return decorator
